14	
15	// --- helpers -------------------------------------------------------------
16	
17	// isolateReadFileHome keeps a test away from the real home directory.
18	func isolateReadFileHome(t *testing.T) {
19		t.Helper()
20		home := t.TempDir()
21		t.Setenv("HOME", home)
22		t.Setenv("USERPROFILE", home)
23	}
24	
25	// probe counts how a test's transcripts are opened and read.
26	type probe struct {
27		opens int
28		bytes int64
29	}
30	
31	// countingFile counts the bytes read through Read and ReadAt.
32	type countingFile struct {
33		transcriptFile
34		p *probe
35	}
36	
37	func (c countingFile) Read(b []byte) (int, error) {
38		n, err := c.transcriptFile.Read(b)
39		c.p.bytes += int64(n)
40		return n, err
41	}
42	
43	func (c countingFile) ReadAt(b []byte, off int64) (int, error) {
44		n, err := c.transcriptFile.ReadAt(b, off)
45		c.p.bytes += int64(n)
46		return n, err
47	}
48	
49	// swapOpen replaces openTranscript for the length of the test.
50	func swapOpen(t *testing.T, fn func(path string) (transcriptFile, error)) {
51		t.Helper()
52		orig := openTranscript
53		openTranscript = fn
54		t.Cleanup(func() { openTranscript = orig })
55	}
56	
57	// countOpens counts opens and bytes read by readFile.
58	func countOpens(t *testing.T) *probe {
59		t.Helper()
60		p := &probe{}
61		orig := openTranscript
62		swapOpen(t, func(path string) (transcriptFile, error) {
63			f, err := orig(path)
64			if err != nil {
65				return nil, err
66			}
67			p.opens++
68			return countingFile{f, p}, nil
69		})
70		return p
71	}
72	
73	var errFault = errors.New("injected read failure")
74	
75	// faultyFile fails with errFault once limit bytes were delivered through Read.
76	type faultyFile struct {
77		transcriptFile
78		limit, n int64
79	}
80	
81	func (f *faultyFile) Read(b []byte) (int, error) {
82		if f.n >= f.limit {
83			return 0, errFault
84		}
85		if rem := f.limit - f.n; int64(len(b)) > rem {
86			b = b[:rem]
87		}
88		n, err := f.transcriptFile.Read(b)
89		f.n += int64(n)
90		return n, err
91	}
92	
93	// faultFirstOpen makes the first open fail after limit bytes; later opens
94	// are normal. It returns a counter of opens.
95	func faultFirstOpen(t *testing.T, limit int64) *probe {
96		t.Helper()
97		p := &probe{}
98		orig := openTranscript
99		swapOpen(t, func(path string) (transcriptFile, error) {
100			f, err := orig(path)
101			if err != nil {
102				return nil, err
103			}
104			p.opens++
105			if p.opens == 1 {
106				return &faultyFile{transcriptFile: f, limit: limit}, nil
107			}
108			return f, nil
109		})
110		return p
111	}
112	
113	func putFile(t *testing.T, path string, data []byte) {
114		t.Helper()
115		if err := os.WriteFile(path, data, 0o600); err != nil {
116			t.Fatal(err)
117		}
118	}
119	
120	func appendFile(t *testing.T, path string, data []byte) {
121		t.Helper()
122		f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0o600)
123		if err != nil {
124			t.Fatal(err)
125		}
126		if _, err := f.Write(data); err != nil {
127			t.Fatal(err)
128		}
129		if err := f.Close(); err != nil {
130			t.Fatal(err)
131		}
132	}
133	
134	// ln is a valid usage line with its newline.
135	func ln(id string) []byte {
136		return append(msgLine(id, "claude-x", "end_turn", 1, 2, 3, 4), '\n')
137	}
138	
139	func cat(parts ...[]byte) []byte { return bytes.Join(parts, nil) }
140	
141	// cur is the cursor of a parent transcript not read yet.
142	func cur(path string) fileCursor {
143		return newFileCursor(path, sanitizeLabel(filepath.Base(path)), "", parentRank)
144	}
145	
146	func pass(fc fileCursor) fileRead { return readFile(fc, time.Now()) }
147	
148	// step reads once and fails if the read asks for a reset.
149	func step(t *testing.T, fc fileCursor) fileRead {
150		t.Helper()
151		fr := pass(fc)
152		if fr.reset {
153			t.Fatal("unexpected reset")
154		}
155		return fr
156	}
157	
158	func fold(dst, part *table) {
159		if part != nil {
160			dst.merge(part)
161		}
162	}
163	
164	// ids returns the message ids held by part, sorted by position.
165	func partIDs(part *table) []string {
166		if part == nil {
167			return nil
168		}
169		var out []string
170		for _, k := range part.orderedKeys() {
171			out = append(out, k.id)
172		}
173		return out
174	}
175	
176	func offOf(t *testing.T, part *table, id string) int64 {
177		t.Helper()
178		if part == nil || part.entries[msgKey{id: id}] == nil {
179			t.Fatalf("message %q not in the part (ids %v)", id, partIDs(part))
180		}
181		return part.entries[msgKey{id: id}].last.off
182	}
183	
184	// assertMatchesParseSession checks the table folded from every part read
185	// equals ParseSession on the final file (D3, the oracle of the story).
186	func assertMatchesParseSession(t *testing.T, path string, tb *table) {
187		t.Helper()
188		want, err := ParseSession(SessionFiles{ID: "s", Parent: path})
189		if err != nil {
190			t.Fatal(err)
191		}
192		agents, diag, versions := tb.finish([]Agent{{Main: true, State: StateUnknown}})
193		want.Diagnostics.TruncatedFiles = nil
194		if !reflect.DeepEqual(agents, want.Agents) {
195			t.Errorf("agents:\n got %+v\nwant %+v", agents, want.Agents)
196		}
197		if !reflect.DeepEqual(diag, want.Diagnostics) {
198			t.Errorf("diagnostics:\n got %+v\nwant %+v", diag, want.Diagnostics)
199		}
200		if !reflect.DeepEqual(versions, want.Versions) {
201			t.Errorf("versions: got %v, want %v", versions, want.Versions)
202		}
203	}
204	
205	// --- appends -------------------------------------------------------------
206	
207	// Criterion 2: a 6 MiB transcript grown by one line costs about that line.
208	func TestReadFileVolumeIsTheAppendedBytes(t *testing.T) {
209		isolateReadFileHome(t)
210		path := filepath.Join(t.TempDir(), "p.jsonl")
211		var buf bytes.Buffer
212		for i := 0; buf.Len() < 6<<20; i++ {
213			buf.Write(ln(fmt.Sprintf("old-%d", i)))
214		}
215		putFile(t, path, buf.Bytes())
216		p := countOpens(t)
217	
218		fr1 := step(t, cur(path))
219		if fr1.part == nil || fr1.next.offset != int64(buf.Len()) {
220			t.Fatalf("first read: part nil=%v offset=%d, want %d", fr1.part == nil, fr1.next.offset, buf.Len())
221		}
222		extra := ln("new")
223		appendFile(t, path, extra)
224		*p = probe{}
225	
226		fr2 := step(t, fr1.next)
227		if limit := int64(len(extra)) + 1; p.bytes > limit {
228			t.Errorf("second read consumed %d bytes, want <= %d", p.bytes, limit)
229		}
230		if got := partIDs(fr2.part); !reflect.DeepEqual(got, []string{"new"}) {
231			t.Errorf("second part ids = %v, want [new]", got)
232		}
233	}
