235	func TestReadFileUnchangedSizeIsNeverOpened(t *testing.T) {
236		isolateReadFileHome(t)
237		path := filepath.Join(t.TempDir(), "p.jsonl")
238		putFile(t, path, cat(ln("a"), ln("b")))
239		p := countOpens(t)
240	
241		fr1 := step(t, cur(path))
242		if p.opens != 1 || fr1.part == nil {
243			t.Fatalf("first read: opens=%d part nil=%v", p.opens, fr1.part == nil)
244		}
245		later := time.Now().Add(-time.Hour).Truncate(time.Second)
246		if err := os.Chtimes(path, later, later); err != nil {
247			t.Fatal(err)
248		}
249		fr2 := step(t, fr1.next)
250		if p.opens != 1 {
251			t.Errorf("opens after a quiet pass = %d, want 1", p.opens)
252		}
253		if fr2.part != nil {
254			t.Errorf("part of a quiet pass = %v, want nil", partIDs(fr2.part))
255		}
256		if !fr2.next.modTime.Equal(later) {
257			t.Errorf("modTime = %v, want the refreshed %v", fr2.next.modTime, later)
258		}
259		if fr2.next.offset != fr1.next.offset || fr2.next.size != fr1.next.size {
260			t.Errorf("position moved on a quiet pass: %+v -> %+v", fr1.next, fr2.next)
261		}
262	}
263	
264	func TestReadFileHeldBackLineIsReadAgainOnceComplete(t *testing.T) {
265		isolateReadFileHome(t)
266		path := filepath.Join(t.TempDir(), "p.jsonl")
267		first := ln("a")
268		whole := ln("h")
269		cut := len(whole) / 2
270		putFile(t, path, cat(first, whole[:cut]))
271	
272		fr1 := step(t, cur(path))
273		if got := partIDs(fr1.part); !reflect.DeepEqual(got, []string{"a"}) {
274			t.Fatalf("first part ids = %v, want [a]", got)
275		}
276		if !fr1.next.tail || fr1.next.offset != int64(len(first)) {
277			t.Fatalf("tail=%v offset=%d, want true and %d", fr1.next.tail, fr1.next.offset, len(first))
278		}
279		appendFile(t, path, whole[cut:])
280		fr2 := step(t, fr1.next)
281		if got := partIDs(fr2.part); !reflect.DeepEqual(got, []string{"h"}) {
282			t.Fatalf("second part ids = %v, want [h]", got)
283		}
284		if off := offOf(t, fr2.part, "h"); off != int64(len(first)) {
285			t.Errorf("held-back line counted at %d, want its original offset %d", off, len(first))
286		}
287		if fr2.next.tail || fr2.next.offset != int64(len(first)+len(whole)) {
288			t.Errorf("tail=%v offset=%d, want false and %d", fr2.next.tail, fr2.next.offset, len(first)+len(whole))
289		}
290	}
