292	// Every byte of a line is a possible split point between two passes; CRLF
293	// terminators and multi-byte runes must not be cut into two readings.
294	func TestReadFileEverySplitPointCountsTheLineOnce(t *testing.T) {
295		isolateReadFileHome(t)
296		multibyte := msgLine("m1", "claude-é😀", "end_turn", 5, 6, 7, 8)
297		tests := []struct {
298			name string
299			line []byte
300		}{
301			{"LF", ln("m1")},
302			{"CRLF", cat(msgLine("m1", "claude-x", "end_turn", 5, 6, 7, 8), []byte("\r\n"))},
303			{"4-byte rune in the model", cat(multibyte, []byte("\n"))},
304		}
305		for _, tc := range tests {
306			t.Run(tc.name, func(t *testing.T) {
307				prefix := ln("m0")
308				for k := 1; k < len(tc.line); k++ {
309					path := filepath.Join(t.TempDir(), "p.jsonl")
310					putFile(t, path, cat(prefix, tc.line[:k]))
311					fr1 := step(t, cur(path))
312					appendFile(t, path, tc.line[k:])
313					fr2 := step(t, fr1.next)
314	
315					all := newTable()
316					fold(all, fr1.part)
317					fold(all, fr2.part)
318					if t.Failed() {
319						return
320					}
321					want := 0
322					for _, id := range append(partIDs(fr1.part), partIDs(fr2.part)...) {
323						if id == "m1" {
324							want++
325						}
326					}
327					if want != 1 {
328						t.Fatalf("split at %d: m1 seen in %d parts, want 1", k, want)
329					}
330					assertMatchesParseSession(t, path, all)
331					if t.Failed() {
332						t.Fatalf("split at %d diverges from a one-shot read", k)
333					}
334				}
335			})
336		}
337	}
