339	// Several passes over a file grown piece by piece equal one full read.
340	func TestReadFileSuccessivePassesEqualAFullRead(t *testing.T) {
341		isolateReadFileHome(t)
342		dup := msgLine("a", "claude-y", "end_turn", 9, 9, 9, 9)
343		tests := []struct {
344			name   string
345			chunks [][]byte
346		}{
347			{"whole lines", [][]byte{cat(ln("a"), ln("b")), ln("c")}},
348			{"line split mid-way", [][]byte{cat(ln("a"), ln("b")[:40]), ln("b")[40:], ln("c")}},
349			{"message rewritten later", [][]byte{ln("a"), cat(dup, []byte("\n")), ln("b")}},
350			{"unreadable line and blank lines", [][]byte{[]byte("not json\n\n"), ln("a"), []byte("{\"x\":\n"), ln("b")}},
351			{"no-id lines", [][]byte{cat(msgLine("", "claude-x", "end_turn", 1, 1, 1, 1), []byte("\n")), cat(msgLine("", "claude-x", "", 2, 2, 2, 2), []byte("\n"))}},
352			{"ends on a held-back line", [][]byte{ln("a"), ln("b")[:25]}},
353			{"empty pass in the middle", [][]byte{ln("a"), nil, ln("b")}},
354		}
355		for _, tc := range tests {
356			t.Run(tc.name, func(t *testing.T) {
357				path := filepath.Join(t.TempDir(), "p.jsonl")
358				putFile(t, path, nil)
359				all := newTable()
360				fc := cur(path)
361				for i, c := range tc.chunks {
362					if i > 0 {
363						appendFile(t, path, c)
364					} else {
365						putFile(t, path, c)
366					}
367					fr := step(t, fc)
368					fold(all, fr.part)
369					fc = fr.next
370				}
371				assertMatchesParseSession(t, path, all)
372				want, _ := ParseSession(SessionFiles{ID: "s", Parent: path})
373				wantTail := len(want.Diagnostics.TruncatedFiles) > 0
374				if fc.tail != wantTail {
375					t.Errorf("tail = %v, ParseSession reports truncated = %v", fc.tail, wantTail)
376				}
377			})
378		}
379	}
