383	func TestReadFileOversizedLineIsCountedOncePerPass(t *testing.T) {
384		isolateReadFileHome(t)
385		path := filepath.Join(t.TempDir(), "p.jsonl")
386		a := ln("a")
387		big := bytes.Repeat([]byte("x"), MaxLineBytes+10)
388		putFile(t, path, cat(a, big, []byte("\n"), ln("b")))
389	
390		all := newTable()
391		fr1 := step(t, cur(path))
392		fold(all, fr1.part)
393		if fr1.part == nil || fr1.part.oversized != 1 {
394			t.Fatalf("first pass oversized = %v, want 1", fr1.part)
395		}
396		appendFile(t, path, ln("c"))
397		fr2 := step(t, fr1.next)
398		fold(all, fr2.part)
399		if fr2.part == nil || fr2.part.oversized != 0 {
400			t.Errorf("second pass recounted the oversized line: %+v", fr2.part)
401		}
402		fr3 := step(t, fr2.next)
403		if fr3.part != nil {
404			t.Errorf("a quiet third pass returned a part: %v", partIDs(fr3.part))
405		}
406		_, diag, _ := all.finish([]Agent{{Main: true}})
407		if diag.OversizedLines != 1 {
408			t.Errorf("OversizedLines = %d, want 1", diag.OversizedLines)
409		}
410		if len(diag.Files) != 1 || diag.Files[0].Kind != IssueOversized || diag.Files[0].Offset != int64(len(a)) {
411			t.Errorf("Files = %+v, want one oversized at offset %d", diag.Files, len(a))
412		}
413		assertMatchesParseSession(t, path, all)
414	}
